// Authored street props (R1-T3, D-057). The SVG sources are embedded in arena-props-data.js (generated by tools/gen-arena-props.js).
// P.ArenaProps.draw(R, x, y, theme, kind, o) draws the authored art for a theme's kit prop and returns true; it returns false while
// the image decodes or when the theme has no authored art for that kind, and P.Props then draws its procedural fallback.
// o.v (0..1) picks the variant. Sign text is written at runtime from a P.t key (the SVG holds no words). View only; the sim never reads this.
P.ArenaProps = (function () {
  var A = {}, IMG = {}, RASTER = {}, pending = 0;
  var FONT = 'italic 900 {px}px "CM Bangers", Bangers, Impact, sans-serif';

  function load() {
    var data = P.ArenaPropsData || {};
    Object.keys(data).forEach(function (id) {
      Object.keys(data[id]).forEach(function (kind) {
        data[id][kind].forEach(function (d, v) {
          var im = new Image(), key = id + '|' + kind + '|' + v;
          pending++;
          im.onload = function () { IMG[key] = im; RASTER = {}; pending--; };
          im.onerror = function () { pending--; };
          im.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(d.svg);
        });
      });
    });
  }

  function raster(key, d, k) {
    var rk = key + '|' + k, t = RASTER[rk], cv;
    if (t) return t;
    cv = document.createElement('canvas'); cv.width = Math.ceil(d.w * k); cv.height = Math.ceil(d.h * k);
    cv.getContext('2d').drawImage(IMG[key], 0, 0, cv.width, cv.height);
    return (RASTER[rk] = cv);
  }

  function label(c, d, X, Y, s) {
    var L = d.label, txt = P.upper(P.t(L.key)), px = Math.round(L.h * s * 0.78);
    c.save(); c.font = FONT.replace('{px}', px); c.textAlign = 'center'; c.textBaseline = 'middle';
    c.fillStyle = L.col; c.fillText(txt, X + (L.x + L.w / 2) * s, Y + (L.y + L.h / 2) * s + 1, L.w * s - 4);
    c.restore();
  }

  A.ready = function () { return pending === 0; };
  A.has = function (theme, kind) { return !!(P.ArenaPropsData && P.ArenaPropsData[theme] && P.ArenaPropsData[theme][kind]); };
  A.draw = function (R, x, y, theme, kind, o) {
    var set = P.ArenaPropsData && P.ArenaPropsData[theme] && P.ArenaPropsData[theme][kind], v, key, d, s, X, Y, c, k;
    if (!set) return false;
    v = Math.min(set.length - 1, Math.floor(((o && o.v) || 0) * set.length)); key = theme + '|' + kind + '|' + v; d = set[v];
    if (!IMG[key]) return false;
    c = R.ctx; s = R.ppm; X = R.X(x); Y = R.Y(y);
    P.Props.h.shadow(c, X, Y, d.fw * s * 0.5, d.fd * s * 0.3);
    k = o && o.w && o.h ? Math.max(0.7, Math.min(1.4, (o.w / d.fw + o.h / d.fd) / 2)) : 1;   // blocks of another size (market stalls) scale the art
    c.drawImage(raster(key, d, Math.max(1, Math.round(s * k * (R.dpr || 1)))), X - d.ax * s * k, Y - d.ay * s * k, d.w * s * k, d.h * s * k);
    if (d.label) label(c, d, X, Y, s * k);
    return true;
  };
  load();
  return A;
})();
